<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: rgba(255, 255, 255, 0.88);
        --surface-strong: #ffffff;
        --text: #182230;
        --muted: #5d6b82;
        --border: rgba(24, 34, 48, 0.12);
        --accent: #6b6ff5;
        --accent-soft: rgba(107, 111, 245, 0.12);
        --shadow: 0 24px 60px rgba(18, 28, 45, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(107, 111, 245, 0.16), transparent 42%),
          linear-gradient(180deg, #fbfcff 0%, var(--bg) 100%);
      }

      .page {
        width: min(920px, calc(100% - 32px));
        margin: 0 auto;
        padding: 64px 0;
      }

      .hero {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 28px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        padding: 40px;
        margin-bottom: 24px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.02em;
        margin: 0 0 16px;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.25rem, 5vw, 4rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lead {
        margin: 16px 0 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 16px;
      }

      .example {
        background: var(--surface-strong);
        border: 1px solid var(--border);
        border-radius: 22px;
        box-shadow: 0 10px 30px rgba(18, 28, 45, 0.06);
        overflow: clip;
      }

      .toggle {
        all: unset;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        width: 100%;
        padding: 24px 26px;
        cursor: pointer;
        font-size: 1.05rem;
        font-weight: 650;
        line-height: 1.4;
      }

      .toggle:focus-visible {
        outline: 3px solid rgba(107, 111, 245, 0.35);
        outline-offset: -3px;
      }

      .chevron {
        flex: none;
        width: 20px;
        height: 20px;
        color: var(--accent);
        transition: transform 180ms ease;
      }

      .example[data-open="true"] .chevron {
        transform: rotate(180deg);
      }

      .details {
        display: grid;
        grid-template-rows: 0fr;
        transition: grid-template-rows 220ms ease;
      }

      .details > div {
        overflow: hidden;
      }

      .details-inner {
        padding: 0 26px 24px;
        color: var(--muted);
        line-height: 1.7;
      }

      .example[data-open="true"] .details {
        grid-template-rows: 1fr;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 920px);
          padding: 20px 0 32px;
        }

        .hero {
          padding: 28px 22px;
          border-radius: 22px;
        }

        .toggle {
          padding: 20px 20px;
        }

        .details-inner {
          padding: 0 20px 20px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="hero" aria-labelledby="faq-title">
        <p class="eyebrow">Cat FAQ</p>
        <h1 id="faq-title">Everything you wanted to know about cats</h1>
        <p class="lead">
          Quick answers about cat behavior, care, and everyday quirks — written for people
          who like their facts as calm and friendly as a sleeping cat.
        </p>
      </section>

      <section class="faq" aria-label="Frequently asked questions">
        <div class="example" data-open="false">
          <button class="toggle" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
            <span>Why do cats purr?</span>
            <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="m6 9 6 6 6-6"></path>
            </svg>
          </button>
          <div class="details" id="answer-1" role="region" aria-labelledby="question-1" hidden>
            <div>
              <div class="details-inner">
                Cats often purr when they feel relaxed, but they may also purr when they are
                hungry, nervous, or seeking comfort. It is one of their most versatile forms of
                communication.
              </div>
            </div>
          </div>
        </div>

        <div class="example" data-open="false">
          <button class="toggle" type="button" aria-expanded="false" aria-controls="answer-2" id="question-2">
            <span>How much sleep do cats need?</span>
            <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="m6 9 6 6 6-6"></path>
            </svg>
          </button>
          <div class="details" id="answer-2" role="region" aria-labelledby="question-2" hidden>
            <div>
              <div class="details-inner">
                Most adult cats sleep between 12 and 16 hours a day. Kittens and senior cats can
                sleep even more, especially after meals and bursts of play.
              </div>
            </div>
          </div>
        </div>

        <div class="example" data-open="false">
          <button class="toggle" type="button" aria-expanded="false" aria-controls="answer-3" id="question-3">
            <span>Why do cats knead with their paws?</span>
            <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="m6 9 6 6 6-6"></path>
            </svg>
          </button>
          <div class="details" id="answer-3" role="region" aria-labelledby="question-3" hidden>
            <div>
              <div class="details-inner">
                Kneading is usually a sign of comfort. Cats often do it when they feel safe, cozy,
                or especially attached to a person or blanket.
              </div>
            </div>
          </div>
        </div>

        <div class="example" data-open="false">
          <button class="toggle" type="button" aria-expanded="false" aria-controls="answer-4" id="question-4">
            <span>Do cats need toys?</span>
            <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="m6 9 6 6 6-6"></path>
            </svg>
          </button>
          <div class="details" id="answer-4" role="region" aria-labelledby="question-4" hidden>
            <div>
              <div class="details-inner">
                Yes. Toys support exercise, mental stimulation, and healthy hunting instincts.
                Rotate a few favorites to keep things interesting.
              </div>
            </div>
          </div>
        </div>
      </section>
    </main>

    <script>
      document.querySelectorAll(".example").forEach((item) => {
        const button = item.querySelector(".toggle");
        const details = item.querySelector(".details");

        button.addEventListener("click", () => {
          const isOpen = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isOpen));
          item.dataset.open = String(!isOpen);
          details.hidden = isOpen;
        });
      });
    </script>
  </body>
</html>
